1	package release
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"os"
8		"path/filepath"
9		"strings"
10		"testing"
11	)
12	
13	// 本文件是“已关闭批次数量核对”在数量上限附近的回归保障：重点保护读取
14	// 已保存关闭结果时，对数量上限附近的负差额仍能精确核对的行为。关闭只确认
15	// 已有投料、不要求数量吻合，因此应投量恰好达到上限（9223372036854775.807
16	// 克）、实投为零或只有 0.001 克、差额为接近上限的负值，都是一次合法关闭
17	// 留下的正常结果，不能因为差额很大或实投为零就当成损坏；反过来，保存结果
18	// 的应投量、实投量或差额只要与配方和实际投料相差 0.001 克，即使仍在数量
19	// 上限内，也必须按 ErrCorruptData 拒绝——原始投料完整不能使写错的关闭
20	// 结果变成合法，查询也不能先用正确计算值替换它再返回成功。负差额的绝对值
21	// 同样不能超过数量上限，保存成 -9223372036854775.808 克时必须明确拒绝，
22	// 不能发生数值回绕、截短或舍入。本文件只补充现有功能的自动化检查，不增加
23	// 放行判断，也不改变关闭批次的条件。
24	//
25	// 复用 feeding_limit_test.go 的 limitGrams（9223372036854775.807）与
26	// corrupt_close_request_result_test.go 的 corruptCloseRequestResult /
27	// mutatedCloseView（均针对 close-b1 请求的保存结果）。
28	
29	// registerLimitRecipe 登记上限核对配方 RL/v1：M1 每份恰为数量上限
30	// 9223372036854775.807 克，M2 每份 1 克（普通用量，用于验证批次中的其他
31	// 物料仍按各自配方用量核对，其数量不参与 M1 差额的计算）。
32	func registerLimitRecipe(t *testing.T, s *Store) {
33		t.Helper()
34		if _, err := s.RegisterRecipe("recipe-rl", "RL", "v1", "上限配方", []MaterialInput{
35			{MaterialNo: "M1", Grams: limitGrams},
36			{MaterialNo: "M2", Grams: "1"},
37		}); err != nil {
38			t.Fatalf("登记 RL/v1 失败: %v", err)
39		}
40	}
41	
42	// setupLimitCloseLedger 在 dir 建立一份上限核对台账并关闭：
43	// RL/v1（M1 每份恰为数量上限、M2 每份 1 克），B1 计划 1 份——M1 的应投量
44	// 恰好等于 9223372036854775.807 克。feedMilli 为 true 时给 M1 投 0.001 克
45	// （请求编号 f1），否则无投料；随后用 close-b1 关闭。
46	// 返回首次关闭成功的结果与落盘后的台账文件内容，供各用例改坏后重写。
47	func setupLimitCloseLedger(t *testing.T, dir string, feedMilli bool) (*BatchView, []byte) {
48		t.Helper()
49		s, err := Open(dir)
50		if err != nil {
51			t.Fatalf("Open 失败: %v", err)
52		}
53		registerLimitRecipe(t, s)
54		if _, err := s.CreateBatch("b1", "B1", "RL", "v1", 1); err != nil {
55			t.Fatal(err)
56		}
57		if _, err := s.StartBatch("start-b1", "B1"); err != nil {
58			t.Fatal(err)
59		}
60		if feedMilli {
61			if _, err := s.AddFeeding("f1", "B1", "M1", "0.001", closeFeedTime(), "张三"); err != nil {
62				t.Fatal(err)
63			}
64		}
65		first, err := s.CloseBatch("close-b1", "B1")
66		if err != nil {
67			t.Fatalf("应投恰达上限的执行中批次应可关闭: %v", err)
68		}
69		if err := s.Close(); err != nil {
70			t.Fatal(err)
71		}
72		good, err := os.ReadFile(filepath.Join(dir, stateFileName))
73		if err != nil {
74			t.Fatal(err)
75		}
76		return first, good
77	}
78	
79	// checkLimitClosedView 校验 B1 关闭后的完整视图（首次关闭的返回结果、
80	// 重放结果或按批次查询的结果都适用）：M1 应投恰为数量上限，实投与差额由
81	// wantActual/wantDiff 给出；M2 按自己的配方用量核对（应投 1、实投 0、
82	// 差额 -1），其数量不参与 M1 差额的计算。
83	func checkLimitClosedView(t *testing.T, v *BatchView, wantActual, wantDiff string) {
84		t.Helper()
85		if v.BatchNo != "B1" || v.RecipeNo != "RL" || v.RecipeVersion != "v1" ||
86			v.RecipeName != "上限配方" || v.PlannedPortions != 1 || v.Status != StatusClosed {
87			t.Fatalf("应为已关闭的 RL/v1、1 份批次 B1，得到 %+v", v)
88		}
89		mats := materialsMap(v)
90		if len(mats) != 2 {
91			t.Fatalf("应只有 M1、M2 两种物料，得到 %d 项: %+v", len(mats), v.Materials)
92		}
93		checkRequirement(t, mats, "M1", limitGrams, wantActual, wantDiff)
94		checkRequirement(t, mats, "M2", "1", "0", "-1")
95	}
96	
97	// 应投量恰好达到数量上限、尚无投料时，关闭结果应保留该应投量、零实投和
98	// -9223372036854775.807 克的差额——关闭表示确认已有投料，不要求数量吻合，
99	// 不能因差额很大或实投为零就把这次合法关闭的结果当成损坏。重新打开台账
100	// 与查询该批次都应成功，重放仍返回第一次关闭时的完整结果。
101	func TestCloseResultAtLimitWithZeroActual(t *testing.T) {
102		dir := t.TempDir()
103		first, _ := setupLimitCloseLedger(t, dir, false)
104		if len(first.Feedings) != 0 {
105			t.Fatalf("无投料批次的投料列表应为空，得到 %d 条: %+v", len(first.Feedings), first.Feedings)
106		}
107		checkLimitClosedView(t, first, "0", "-"+limitGrams)
108	
109		s2, err := Open(dir)
110		if err != nil {
111			t.Fatalf("应投恰达上限、零实投、负差额的关闭结果不应判为损坏: %v", err)
112		}
113		defer s2.Close()
114		replay, err := s2.CloseBatch("close-b1", "B1")
115		if err != nil {
116			t.Fatalf("重放关闭请求应成功: %v", err)
117		}
118		checkLimitClosedView(t, replay, "0", "-"+limitGrams)
119		checkLimitClosedView(t, mustGetBatch(t, s2, "B1"), "0", "-"+limitGrams)
120	}
121	
122	// 应投量恰达上限、只投了 0.001 克时，关闭结果的实投应为 0.001 克，差额
123	// 应为 -9223372036854775.806 克：不能丢掉这千分之一克，也不能把负差额
124	// 翻成正数。重新打开台账与查询该批次都应成功，重放结果一致。
125	func TestCloseResultAtLimitWithMilliActual(t *testing.T) {
126		dir := t.TempDir()
127		first, _ := setupLimitCloseLedger(t, dir, true)
128		if len(first.Feedings) != 1 || first.Feedings[0].Seq != 1 ||
129			first.Feedings[0].MaterialNo != "M1" || first.Feedings[0].Grams != "0.001" {
130			t.Fatalf("应保留 0.001 克的投料记录，得到 %+v", first.Feedings)
131		}
132		checkLimitClosedView(t, first, "0.001", "-9223372036854775.806")
133	
134		s2, err := Open(dir)
135		if err != nil {
136			t.Fatalf("实投 0.001 克、负差额接近上限的关闭结果不应判为损坏: %v", err)
137		}
138		defer s2.Close()
139		replay, err := s2.CloseBatch("close-b1", "B1")
140		if err != nil {
141			t.Fatalf("重放关闭请求应成功: %v", err)
142		}
143		checkLimitClosedView(t, replay, "0.001", "-9223372036854775.806")
144		got := mustGetBatch(t, s2, "B1")
145		checkLimitClosedView(t, got, "0.001", "-9223372036854775.806")
146		if len(got.Feedings) != 1 || got.Feedings[0].Grams != "0.001" {
147			t.Fatalf("查询应保留 0.001 克的投料记录，得到 %+v", got.Feedings)
148		}
149	}
150	
151	// 正常写法差异不能误判为损坏：合法范围内 1 与 1.000、0 与 0.000、-1 与
152	// -1.000 是相同数量，不能只因末尾的零不同拒绝读取。台账应正常打开，
153	// 重放返回保存的写法，查询返回规范化写法。
154	func TestCloseResultAtLimitAcceptsFormatVariants(t *testing.T) {
155		dir := t.TempDir()
156		_, good := setupLimitCloseLedger(t, dir, false)
157	
158		bad := corruptCloseRequestResult(t, good, func() json.RawMessage {
159			return mutatedCloseView(t, good, func(v *BatchView) {
160				v.Materials[0].ActualGrams = "0.000"      // 与 0 是同一数量
161				v.Materials[1].RequiredGrams = "1.000"    // 与 1 是同一数量
162				v.Materials[1].ActualGrams = "0.000"      // 与 0 是同一数量
163				v.Materials[1].DifferenceGrams = "-1.000" // 与 -1 是同一数量
164			})
165		})
166		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
167			t.Fatal(err)
168		}
169	
170		s, err := Open(dir)
171		if err != nil {
172			t.Fatalf("末尾零的写法差异不应判为损坏: %v", err)
173		}
174		defer s.Close()
175	
176		// 重放取回保存的结果原文：保持 0.000、1.000、-1.000 的写法。
177		replay, err := s.CloseBatch("close-b1", "B1")
178		if err != nil {
179			t.Fatalf("重放关闭请求应成功: %v", err)
180		}
181		mats := materialsMap(replay)
182		if mats["M1"].ActualGrams != "0.000" || mats["M2"].RequiredGrams != "1.000" ||
183			mats["M2"].ActualGrams != "0.000" || mats["M2"].DifferenceGrams != "-1.000" {
184			t.Fatalf("重放应返回保存的核对项写法，得到 %+v", replay.Materials)
185		}
186		// 按批次查询得到系统规范化写法的视图，数量与首次关闭一致。
187		checkLimitClosedView(t, mustGetBatch(t, s, "B1"), "0", "-"+limitGrams)
188	}
189	
190	// 保存结果的应投量、实投量或差额只要与配方和实际投料相差 0.001 克，即使
191	// 仍在数量上限内，也必须返回 ErrCorruptData：数量相同与数量不符之间的
192	// 区别必须保住，原始投料完整不能使写错的关闭结果变成合法。错误信息应指出
193	// 关闭请求编号、批次编号及对应物料，原台账内容保持不变。
194	func TestOpenRejectsCloseResultOffByMilliNearLimit(t *testing.T) {
195		cases := []struct {
196			name      string
197			feedMilli bool // 是否使用投过 0.001 克的台账
198			edit      func(v *BatchView)
199			material  string // 错误信息应指出的物料
200		}{
201			{"应投量少 0.001", false, func(v *BatchView) {
202				v.Materials[0].RequiredGrams = "9223372036854775.806"
203			}, "M1"},
204			{"实投量多出 0.001", false, func(v *BatchView) {
205				v.Materials[0].ActualGrams = "0.001"
206			}, "M1"},
207			{"负差额少算 0.001", false, func(v *BatchView) {
208				v.Materials[0].DifferenceGrams = "-9223372036854775.806"
209			}, "M1"},
210			{"负差额被翻成正数", false, func(v *BatchView) {
211				v.Materials[0].DifferenceGrams = limitGrams
212			}, "M1"},
213			{"其他物料差额差 0.001", false, func(v *BatchView) {
214				v.Materials[1].DifferenceGrams = "-1.001"
215			}, "M2"},
216			{"实投丢掉千分之一克", true, func(v *BatchView) {
217				v.Materials[0].ActualGrams = "0"
218			}, "M1"},
219			{"已投 0.001 时差额多算 0.001", true, func(v *BatchView) {
220				v.Materials[0].DifferenceGrams = "-9223372036854775.807"
221			}, "M1"},
222		}
223		for _, tc := range cases {
224			t.Run(tc.name, func(t *testing.T) {
225				dir := t.TempDir()
226				_, good := setupLimitCloseLedger(t, dir, tc.feedMilli)
227				bad := corruptCloseRequestResult(t, good, func() json.RawMessage {
228					return mutatedCloseView(t, good, tc.edit)
229				})
230				if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
231					t.Fatal(err)
232				}
233	
234				s, err := Open(dir)
235				if !errors.Is(err, ErrCorruptData) {
236					t.Fatalf("相差 0.001 克的关闭结果应返回 ErrCorruptData，得到 %v", err)
237				}
238				if s != nil {
239					s.Close()
240					t.Fatalf("损坏台账不应返回可用的 Store 对象")
241				}
242				msg := err.Error()
243				for _, want := range []string{"close-b1", "B1", tc.material} {
244					if !strings.Contains(msg, want) {
245						t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
246					}
247				}
248				got, err := os.ReadFile(filepath.Join(dir, stateFileName))
249				if err != nil {
250					t.Fatal(err)
251				}
252				if !bytes.Equal(got, bad) {
253					t.Fatalf("拒绝打开不应改动台账文件")
254				}
255			})
256		}
257	}
258	
259	// 台账正常打开后，保存内容中的关闭结果被改坏（差额差 0.001 克，原始投料
260	// 保持完整）：下一次查询与重放都必须返回 ErrCorruptData——查询不能先用
261	// 正确计算值替换写错的保存结果再返回成功，重放也不能把损坏结果当成第一次
262	// 关闭的结果。被拒绝的访问不改动原台账内容。
263	func TestCloseResultCorruptionNearLimitNotHealedByRecompute(t *testing.T) {
264		dir := t.TempDir()
265		_, good := setupLimitCloseLedger(t, dir, true)
266	
267		s, err := Open(dir)
268		if err != nil {
269			t.Fatalf("Open 失败: %v", err)
270		}
271		defer s.Close()
272	
273		// 打开后把 close-b1 保存结果的差额改坏 0.001 克：原始投料（0.001 克）
274		// 与应投量都保持完整，只有核对差额与配方和实际投料不符。
275		bad := corruptCloseRequestResult(t, good, func() json.RawMessage {
276			return mutatedCloseView(t, good, func(v *BatchView) {
277				v.Materials[0].DifferenceGrams = "-9223372036854775.807"
278			})
279		})
280		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
281			t.Fatal(err)
282		}
283	
284		// 查询该批次：不能用重算的正确差额覆盖写错的保存结果后返回成功。
285		if v, err := s.GetBatch("B1"); !errors.Is(err, ErrCorruptData) {
286			t.Fatalf("查询应返回 ErrCorruptData，得到 %v", err)
287		} else if v != nil {
288			t.Fatalf("被拒绝的查询不应返回部分台账视图: %+v", v)
289		}
290		// 重放关闭请求：不能把损坏的保存结果当成第一次关闭的结果返回。
291		if _, err := s.CloseBatch("close-b1", "B1"); !errors.Is(err, ErrCorruptData) {
292			t.Fatalf("重放损坏的关闭请求应返回 ErrCorruptData，得到 %v", err)
293		}
294	
295		after, err := os.ReadFile(filepath.Join(dir, stateFileName))
296		if err != nil {
297			t.Fatal(err)
298		}
299		if !bytes.Equal(after, bad) {
300			t.Fatalf("被拒绝的访问不应改动台账文件")
301		}
302	}
303	
304	// 负差额的绝对值同样不能超过数量上限：保存成 -9223372036854775.808 克
305	// （或更大的负值）时必须明确拒绝，不能发生数值回绕、截短或舍入后当成合法
306	// 结果读取。应投量超过上限的写法同理。错误信息应指出关闭请求编号、批次
307	// 编号及对应物料的数量问题，原台账内容保持不变。
308	func TestOpenRejectsCloseResultQuantityBeyondLimit(t *testing.T) {
309		cases := []struct {
310			name string
311			edit func(v *BatchView)
312		}{
313			{"负差额绝对值超上限 0.001", func(v *BatchView) {
314				v.Materials[0].DifferenceGrams = "-9223372036854775.808"
315			}},
316			{"负差额整数部分超上限", func(v *BatchView) {
317				v.Materials[0].DifferenceGrams = "-9223372036854776"
318			}},
319			{"负差额远超 int64 不能回绕", func(v *BatchView) {
320				v.Materials[0].DifferenceGrams = "-18446744073709551.615"
321			}},
322			{"应投量超上限 0.001", func(v *BatchView) {
323				v.Materials[0].RequiredGrams = "9223372036854775.808"
324			}},
325		}
326		for _, tc := range cases {
327			t.Run(tc.name, func(t *testing.T) {
328				dir := t.TempDir()
329				_, good := setupLimitCloseLedger(t, dir, false)
330				bad := corruptCloseRequestResult(t, good, func() json.RawMessage {
331					return mutatedCloseView(t, good, tc.edit)
332				})
333				if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
334					t.Fatal(err)
335				}
336	
337				s, err := Open(dir)
338				if !errors.Is(err, ErrCorruptData) {
339					t.Fatalf("超出数量上限的关闭结果应返回 ErrCorruptData，得到 %v", err)
340				}
341				if s != nil {
342					s.Close()
343					t.Fatalf("损坏台账不应返回可用的 Store 对象")
344				}
345				msg := err.Error()
346				for _, want := range []string{"close-b1", "B1", "M1"} {
347					if !strings.Contains(msg, want) {
348						t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
349					}
350				}
351				got, err := os.ReadFile(filepath.Join(dir, stateFileName))
352				if err != nil {
353					t.Fatal(err)
354				}
355				if !bytes.Equal(got, bad) {
356					t.Fatalf("拒绝打开不应改动台账文件")
357				}
358			})
359		}
360	}
