369			t.Fatal(err)
370		}
371		// M1：应投 1000，先投 1000 再投 500（超投 500）。
372		if _, err := s.AddFeeding("f1", "B1", "M1", "1000", time.Now(), "张三"); err != nil {
373			t.Fatal(err)
374		}
375		if _, err := s.AddFeeding("f2", "B1", "M1", "500", time.Now(), "张三"); err != nil {
376			t.Fatal(err)
377		}
378		// M2：应投 5，投 3（欠 2）。M3 不投料。
379		if _, err := s.AddFeeding("f3", "B1", "M2", "3", time.Now(), "李四"); err != nil {
380			t.Fatal(err)
