383		view, err := s.GetBatch("B1")
384		if err != nil {
385			t.Fatal(err)
386		}
387		got := map[string]MaterialRequirement{}
388		for _, m := range view.Materials {
389			got[m.MaterialNo] = m
390		}
391		check := func(mat, req, act, diff string) {
392			t.Helper()
393			m, ok := got[mat]
394			if !ok {
395				t.Fatalf("缺少物料 %q", mat)
396			}
397			if m.RequiredGrams != req || m.ActualGrams != act || m.DifferenceGrams != diff {
398				t.Fatalf("物料 %q 核对应为 应投=%s 实投=%s 差额=%s，得到 %+v", mat, req, act, diff, m)
399			}
400		}
401		check("M1", "1000", "1500", "500")
402		check("M2", "5", "3", "-2")
403		check("M3", "0.1", "0", "-0.1")
404	}
