572	// 请求编号冲突：同一编号用于不同操作或不同内容必须拒绝。
573	func TestRequestConflict(t *testing.T) {
574		s := openTestStore(t)
575		registerStandardRecipe(t, s, "recipe-1")
576		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
577			t.Fatal(err)
578		}
579	
580		// 同编号、不同内容（份数不同）。
581		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 20); !errors.Is(err, ErrRequestConflict) {
582			t.Fatalf("同编号不同内容应返回 ErrRequestConflict，得到 %v", err)
583		}
584		// 同编号、不同操作。
585		if _, err := s.StartBatch("b1", "B1"); !errors.Is(err, ErrRequestConflict) {
586			t.Fatalf("同编号不同操作应返回 ErrRequestConflict，得到 %v", err)
587		}
588		if _, err := s.AddFeeding("b1", "B1", "M1", "10", time.Now(), "张三"); !errors.Is(err, ErrRequestConflict) {
589			t.Fatalf("同编号不同操作应返回 ErrRequestConflict，得到 %v", err)
590		}
591		// 冲突拒绝后原数据不变。
592		got, _ := s.GetBatch("B1")
593		if got.Status != StatusDraft || got.PlannedPortions != 10 {
594			t.Fatalf("冲突请求不应改变数据: %+v", got)
